<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Service\Visibility\TemplateSnippetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetReadGateway;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetFilter;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetCursor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateSnippetListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateSnippetVisibilityService $visibility,
        private readonly TemplateSnippetReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Template snippet");
        $span = $this->startSpan("Check allow of list usecase for Template snippet");
        try {
            $result = $this->dispatcher->dispatch(new TemplateSnippetListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(TemplateSnippetFilter $filter): int
    {
        $this->logDebug("Run list usecase for Template snippet");
        $span = $this->startSpan("Run list usecase for Template snippet");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Template snippet');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(TemplateSnippetFilter $filter, ?TemplateSnippetCursor $cursor = null): TemplateSnippetAttributesSlide
    {
        $this->logDebug("Run list usecase for Template snippet");
        $span = $this->startSpan("Run list usecase for Template snippet");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new TemplateSnippetAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
